package com.gymmind.workout.domain.model;
import com.gymmind.shared.persistence.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="workout_set") public class WorkoutSet extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="record_id",nullable=false) private WorkoutRecord record; @Column(name="exercise_id",nullable=false) private Long exerciseId; @Column(name="set_number",nullable=false) private int setNumber; @Column(nullable=false) private double weight; @Column(nullable=false) private int reps; @Column(nullable=false) private int duration; @Column(nullable=false) private boolean completed; protected WorkoutSet(){} private WorkoutSet(WorkoutRecord r,Long e,int n,double w,int reps,int dur,boolean c){if(r==null||e==null||e<=0||n<=0||w<0||reps<0||dur<0)throw new IllegalArgumentException("Invalid workout set");record=r;exerciseId=e;setNumber=n;weight=w;this.reps=reps;duration=dur;completed=c;} public static WorkoutSet create(WorkoutRecord r,Long e,int n,double w,int reps,int dur,boolean c){return new WorkoutSet(r,e,n,w,reps,dur,c);} public WorkoutRecord getRecord(){return record;} public Long getExerciseId(){return exerciseId;} public int getSetNumber(){return setNumber;} public double getWeight(){return weight;} public int getReps(){return reps;} public int getDuration(){return duration;} public boolean isCompleted(){return completed;} }
